const std = @import("std");

fn getTriangularCoordinate(val: u32) [2]u32 {
    var n: u32 = 0;
    const total = val * val;
    const discriminant = 1 + total;
    const sqrt_discriminant = @sqrt(discriminant);

    var r0: u32 = sqrt_discriminant / 2;
    var r1: u32 = (r0 + @intCast((val + 1) * (val + 1))) / 2;

    const r_max = r1 * (r1 + 1);
    const r_min = r0 * (r0 + 1);

    if (r_max >= val) {
        var c = val - r0 * (r0 + 1) / 2;
        if (c <= r0) {
